/**
 * The system API (/api/ev/system, webapp/evsystem.py). Types are written here, to match the server's answers,
 * because the generated schema (src/api/schema.d.ts) is regenerated by the integration step, not by this page.
 */
import { useQuery } from "@tanstack/react-query"

import { getJson } from "@/api/client"

/** The state of a question's batch plan file. */
export type BatchPlanState = "missing" | "draft" | "confirmed" | "stale"

export interface SystemQuestion {
  id: string
  question: string
  sub_questions: string[]
  kind: string
  target: string | null
  plan: BatchPlanState
}

export interface SystemDomain {
  domain: string
  seeds: number[]
  questions: SystemQuestion[]
  error: string | null
}

export interface StepFact {
  n: number
  item: string
  paper: string
  type: string
  text: string
}

export interface AnswerLine {
  text: string
  facts: number[]
}

export interface SystemSteps {
  status: "running" | "failed" | "done"
  error?: string | null
  answer_by: string
  question: string
  program_refused: string | null
  find: { count: number; papers: { paper: string; kept: boolean; why: string }[] }
  pull: { count: number; left_out: number; facts: StepFact[] }
  combine: { rule: string; count: number; rows: { text: string; facts: number[] }[] }
  answer: { text: string; status: string; problems: string[]; lines: AnswerLine[] }
}

export interface PaperView {
  paper: string
  text: string
  segments: { text: string; start: number; end: number; marks: string[]; roles: string[] }[]
}

const enc = encodeURIComponent

export function useSystemDomains() {
  return useQuery({ queryKey: ["system-domains"], queryFn: () => getJson<SystemDomain[]>("/api/ev/system/domains") })
}

/** The four rows of a run; polls while the run is going. */
export function useSteps(rid: string | null, enabled: boolean) {
  return useQuery({
    queryKey: ["system-steps", rid],
    queryFn: () => getJson<SystemSteps>(`/api/ev/system/runs/${enc(rid as string)}/steps`),
    enabled: rid !== null && enabled,
    refetchInterval: (query) => (query.state.data?.status === "running" ? 2000 : false),
  })
}

export function usePaper(rid: string | null, doc: string | null) {
  return useQuery({
    queryKey: ["system-paper", rid, doc],
    queryFn: () => getJson<PaperView>(`/api/ev/system/runs/${enc(rid as string)}/papers/${enc(doc as string)}`),
    enabled: rid !== null && doc !== null,
  })
}

/**
 * A failed run's reason. The server never sends a failed status: a failed run comes back as status "done" with the
 * answer text "failed: <reason>" and no lines (webapp/planwire.py).
 */
export function runFailure(result: { status?: string; answer?: { text?: string } } | undefined): string | null {
  const text = result?.answer?.text
  return result?.status === "done" && typeof text === "string" && text.startsWith("failed:") ? text : null
}
